-- C12 / P12.8 — specialist isolation, lifecycle recovery, provider-failure locality, and future registration.
create table if not exists public.command_center_specialist_type_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 type_event_id text not null check(btrim(type_event_id)<>''), type_key text not null check(btrim(type_key)<>''), truth_owner text not null check(btrim(truth_owner)<>''), isolation_class text not null check(btrim(isolation_class)<>''), required_provider_capabilities text[] not null default '{}'::text[], source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,type_event_id), unique(owner_id,type_key,observed_at)
);
create table if not exists public.command_center_specialist_lifecycle_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 lifecycle_event_id text not null check(btrim(lifecycle_event_id)<>''), project_id text not null check(btrim(project_id)<>''), type_key text not null check(btrim(type_key)<>''), display_name text not null check(btrim(display_name)<>''), canonical_ref text not null check(btrim(canonical_ref)<>''), status text not null check(status in ('active','dormant','archived','replaced')), provider_capabilities text[] not null default '{}'::text[], replaced_by_project_id text, authorization_ref text, source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,lifecycle_event_id), unique(owner_id,project_id,observed_at), check(replaced_by_project_id is null or btrim(replaced_by_project_id)<>''), check(authorization_ref is null or btrim(authorization_ref)<>'')
);
create table if not exists public.command_center_specialist_provider_assessment_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 assessment_event_id text not null check(btrim(assessment_event_id)<>''), project_id text not null check(btrim(project_id)<>''), provider_capability text not null check(btrim(provider_capability)<>''), health text not null check(health in ('available','degraded','unavailable')), isolated_failure boolean not null, source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,assessment_event_id), check(isolated_failure=(health<>'available'))
);
create or replace view public.command_center_specialist_lifecycle_current with (security_invoker=true) as select distinct on(owner_id,project_id) owner_id,lifecycle_event_id,project_id,type_key,display_name,canonical_ref,status,provider_capabilities,replaced_by_project_id,authorization_ref,source_refs,observed_at from public.command_center_specialist_lifecycle_history order by owner_id,project_id,observed_at desc;
create or replace function public.command_center_reject_specialist_lifecycle_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Specialist lifecycle evidence is immutable'; end $$;
drop trigger if exists command_center_specialist_type_immutable on public.command_center_specialist_type_history; create trigger command_center_specialist_type_immutable before update or delete on public.command_center_specialist_type_history for each row execute function public.command_center_reject_specialist_lifecycle_mutation();
drop trigger if exists command_center_specialist_lifecycle_immutable on public.command_center_specialist_lifecycle_history; create trigger command_center_specialist_lifecycle_immutable before update or delete on public.command_center_specialist_lifecycle_history for each row execute function public.command_center_reject_specialist_lifecycle_mutation();
drop trigger if exists command_center_specialist_provider_assessment_immutable on public.command_center_specialist_provider_assessment_history; create trigger command_center_specialist_provider_assessment_immutable before update or delete on public.command_center_specialist_provider_assessment_history for each row execute function public.command_center_reject_specialist_lifecycle_mutation();
alter table public.command_center_specialist_type_history enable row level security; alter table public.command_center_specialist_lifecycle_history enable row level security; alter table public.command_center_specialist_provider_assessment_history enable row level security;
revoke all on table public.command_center_specialist_type_history,public.command_center_specialist_lifecycle_history,public.command_center_specialist_provider_assessment_history from public,anon,authenticated; grant select,insert on table public.command_center_specialist_type_history,public.command_center_specialist_lifecycle_history,public.command_center_specialist_provider_assessment_history to authenticated; grant select on table public.command_center_specialist_lifecycle_current to authenticated;
create policy p12_8_specialist_type_owner on public.command_center_specialist_type_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p12_8_specialist_lifecycle_owner on public.command_center_specialist_lifecycle_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p12_8_specialist_provider_assessment_owner on public.command_center_specialist_provider_assessment_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
